SELECT file_id, file_name, file_url, file_size, file_type, entity_id, entity_type, is_representative, uploaded_at
FROM files
WHERE file_id = #{fileId}

SELECT file_id, file_name, file_url, file_size, file_type, entity_id, entity_type, is_representative, uploaded_at
FROM files
WHERE entity_type = #{entityType}
AND entity_id = #{entityId}
ORDER BY file_id ASC
